<script setup lang="ts">import{ref,computed,onMounted,watch}from 'vue';import{useRoute}from 'vue-router';import{lab,load}from '../stores/research';import{detail}from '../api/jointRuns';import{useTask}from '../hooks/useTask';import{usePolling}from '../hooks/usePolling';import{fmt,bearing}from '../utils/format';import{fitStates}from '../constants/enums';import type{JointRun,Energy}from '../types/domain';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import RunSelect from '../components/RunSelect.vue';import StatusBadge from '../components/common/StatusBadge.vue';import PolarPlot from '../components/PolarPlot.vue';import EnergyPlot from '../components/EnergyPlot.vue';const route=useRoute(),id=ref(Number(route.query.run)||0),jointId=ref(Number(route.query.joint)||0),viewing=ref<'pair'|'joint'>(route.query.joint?'joint':'pair'),{error,execute}=useTask(),jointRun=ref<JointRun|null>(null),pairIndex=ref(0);const run=computed(()=>lab.runs.find(r=>r.id===id.value));async function openJoint(){jointRun.value=jointId.value?await detail(jointId.value):null;pairIndex.value=0}onMounted(()=>execute(async()=>{await load();if(!id.value&&!jointId.value){id.value=lab.runs.find(r=>r.status==='completed')?.id||0;jointId.value=lab.jointRuns.find(r=>r.status==='completed')?.id||0;if(!id.value&&jointId.value)viewing.value='joint'}await openJoint()}));watch(()=>route.query.run,v=>{if(v){id.value=Number(v);viewing.value='pair'}});watch(()=>route.query.joint,v=>{if(v){jointId.value=Number(v);viewing.value='joint';execute(openJoint)}});watch(jointId,()=>execute(openJoint));usePolling(()=>{if(run.value&&['queued','running'].includes(run.value.status))execute(load);if(jointRun.value&&['queued','running'].includes(jointRun.value.status))execute(async()=>{await load();await openJoint()})});const sortedPairs=computed(()=>[...(jointRun.value?.result.pairs||[])].map((p,m)=>({...p,m})).sort((x,y)=>x.rank-y.rank));const minRaw=computed(()=>Math.min(...(jointRun.value?.result.pairs||[]).map(p=>p.p_raw),1));const minAdjusted=computed(()=>Math.min(...(jointRun.value?.result.pairs||[]).map(p=>p.p_adjusted),1));const pairEnergy=computed<Energy|null>(()=>{const r=jointRun.value;if(!r?.result.pairs||!r.result.joint||!r.null_statistics?.length)return null;const p=r.result.pairs[pairIndex.value];if(!p)return null;const column=r.null_statistics.map(row=>row[pairIndex.value]);const sorted=[...column].sort((x,y)=>x-y);const q=(f:number)=>sorted[Math.min(sorted.length-1,Math.floor(f*sorted.length))];return{statistic:p.statistic,p_value:p.p_raw,extreme:p.extreme,permutations:r.result.joint.permutations,seed:r.result.joint.seed,null_statistics:column,null_quantiles:[q(.025),q(.5),q(.975)],definition:r.result.joint.definition}});</script><template><PageHeading index="04" title="均值有边界，差异有前提。" text="从形状读到合向量，再看标签置换。联合研究统一重分全部标签，原始p与逐步校正p分列。完整研究包含原始输入快照、分组、seed与SHA256。"><RouterLink v-if="viewing==='pair'&&run?.status==='completed'" class="outline" :to="'/notes?run='+run.id">建立观察说明 ↗</RouterLink><RouterLink v-if="viewing==='joint'&&jointRun?.status==='completed'" class="outline" :to="'/notes?joint='+jointRun.id">建立观察说明 ↗</RouterLink></PageHeading><ErrorNotice :message="error" @retry="execute(load)"/><div class="run-select"><RunSelect v-model="id" :runs="lab.runs" @update:model-value="viewing='pair'"/><label v-if="lab.jointRuns.length" class="joint-select">联合研究档案<select v-model="jointId" @change="viewing='joint'"><option v-for="r in lab.jointRuns" :value="r.id">#{{r.id}} {{r.name}}</option></select></label><StatusBadge v-if="viewing==='joint'&&lab.jointRuns.find(r=>r.id===jointId)" :status="lab.jointRuns.find(r=>r.id===jointId)!.status"/></div><template v-if="viewing==='joint'"><template v-if="jointRun?.status==='completed'&&jointRun.result.pairs&&jointRun.result.joint&&jointRun.result.groups"><div class="energy-summary"><div><p class="eyebrow">JOINT GROUPS / PAIRS</p><h2>{{jointRun.result.joint.group_count}} / {{jointRun.result.joint.pair_count}}</h2><p>座浮标 / 对并列比较</p></div><div><p class="eyebrow">MIN RAW → ADJUSTED P</p><h2>{{fmt(minRaw,4)}} → {{fmt(minAdjusted,4)}}</h2><p>{{jointRun.result.joint.permutations}}次统一重分 / seed{{jointRun.seed}}</p></div><p>{{jointRun.result.interpretation}}</p></div><section class="register"><div class="section-title"><h2>各对并列比较：原始p与逐步校正p分列</h2><span>按观测统计量降序；点选一行查看该对零分布</span></div><div class="table-wrap"><table class="pairs-table"><thead><tr><th>秩次</th><th>浮标对</th><th>统计量</th><th>原始p</th><th>校正p</th><th>达到次数</th></tr></thead><tbody><tr v-for="p in sortedPairs" :key="p.m" :class="{selected:p.m===pairIndex}" @click="pairIndex=p.m"><td>{{p.rank}}</td><td>{{p.mooring_a}} – {{p.mooring_b}}</td><td class="numeric">{{fmt(p.statistic,4)}}</td><td class="numeric">{{fmt(p.p_raw,4)}}</td><td class="numeric adjusted">{{fmt(p.p_adjusted,4)}}</td><td>{{p.extreme}}</td></tr></tbody></table></div><p class="plot-note">校正方法：{{jointRun.result.joint.correction}}</p></section><EnergyPlot v-if="pairEnergy" :energy="pairEnergy"/><section class="register"><div class="section-title"><h2>各组圆周描述</h2><span>同一调查期 {{jointRun.result.joint.group_count}} 座浮标</span></div><div class="table-wrap"><table><thead><tr><th>浮标</th><th>样本</th><th>圆周均值</th><th>合向量 R</th><th>R₂</th><th>集中度 κ</th><th>拟合状态</th></tr></thead><tbody><tr v-for="g in jointRun.result.groups" :key="g.mooring_id"><td>{{g.code}} · {{g.name}}</td><td>{{g.n}}</td><td>{{bearing(g.mean_bearing)}}</td><td>{{fmt(g.resultant,4)}}</td><td>{{fmt(g.second_resultant,4)}}</td><td>{{fmt(g.kappa,3)}}</td><td>{{fitStates[g.fit_status]}}</td></tr></tbody></table></div><p class="fingerprint">输入SHA256 {{jointRun.result.fingerprint}}</p><details><summary>读取完整JSON与输入快照</summary><pre>{{JSON.stringify(jointRun.result,null,2)}}</pre></details></section></template><div v-else class="empty"><h2>{{jointRun?.status==='failed'?'联合研究未完成':'等待联合研究结果'}}</h2><p>{{jointRun?.error||'队列中自动刷新；也可重新读取或建立第一份联合研究。'}}</p><button class="outline" @click="execute(async()=>{await load();await openJoint()})">重新读取</button><RouterLink to="/configure">研究配置 ↗</RouterLink></div></template><template v-else><template v-if="run?.status==='completed'&&run.result.a&&run.result.b&&run.result.energy"><div class="result-top"><PolarPlot :a="run.result.a" :b="run.result.b"/><section class="circular-reading"><p class="eyebrow">CIRCULAR MOMENTS / VON MISES</p><article v-for="(g,i) in [run.result.a,run.result.b]"><h2>{{i?'B':'A'}}组 · {{g.n}}条</h2><dl><div><dt>圆周均值</dt><dd>{{bearing(g.mean_bearing)}}</dd></div><div><dt>合向量 R</dt><dd>{{fmt(g.resultant,4)}}</dd></div><div><dt>二阶合向量 R₂</dt><dd>{{fmt(g.second_resultant,4)}}</dd></div><div><dt>集中度 κ</dt><dd>{{fmt(g.kappa,3)}}</dd></div></dl><p class="fit-state">{{fitStates[g.fit_status]}}</p><p class="plot-note">{{g.warning}}</p></article></section></div><div class="energy-summary"><div><p class="eyebrow">DISTRIBUTION ENERGY</p><h2>{{fmt(run.result.energy.statistic,5)}}</h2><p>单位圆弦距离V统计量</p></div><div><p class="eyebrow">PERMUTATION P</p><h2>{{fmt(run.result.energy.p_value,4)}}</h2><p>{{run.result.energy.permutations}}次置换 / seed{{run.seed}}</p></div><p>{{run.result.interpretation}}</p></div><EnergyPlot :energy="run.result.energy"/><section class="register"><div class="section-title"><h2>同一扇区，观测与单峰描述分列</h2><span>每格角度为左闭右开；最后一格不包括360°</span></div><div class="table-wrap"><table><thead><tr><th>方向扇区</th><th>A计数</th><th>A比例</th><th>A模型概率</th><th>B计数</th><th>B比例</th><th>B模型概率</th></tr></thead><tbody><tr v-for="(h,i) in run.result.a.histogram"><td>{{h.lower}}–{{h.upper}}°</td><td>{{h.count}}</td><td>{{fmt(h.proportion,4)}}</td><td>{{fmt(h.fitted_probability,4)}}</td><td>{{run.result.b.histogram[i].count}}</td><td>{{fmt(run.result.b.histogram[i].proportion,4)}}</td><td>{{fmt(run.result.b.histogram[i].fitted_probability,4)}}</td></tr></tbody></table></div><p class="fingerprint">输入SHA256 {{run.result.fingerprint}}</p><details><summary>读取完整JSON与输入快照</summary><pre>{{JSON.stringify(run.result,null,2)}}</pre></details></section></template><div v-else class="empty"><h2>{{run?.status==='failed'?'研究未完成':'等待圆周研究结果'}}</h2><p>{{run?.error||'队列中自动刷新；也可重新读取或建立第一份研究。'}}</p><button class="outline" @click="execute(load)">重新读取</button><RouterLink to="/configure">研究配置 ↗</RouterLink></div></template></template>
